  "inlineSchema": "// Schema del database — vedi docs/implementation-plan.md per il contesto.\n// Stack: PostgreSQL (Neon) + Prisma.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// ---------------------------------------------------------------------------\n// Utenti e ruoli\n// ---------------------------------------------------------------------------\n\nenum Ruolo {\n  CLIENTE\n  VENDITORE\n  ADMIN\n}\n\nmodel Utente {\n  id            Int      @id @default(autoincrement())\n  role          Ruolo    @default(CLIENTE)\n  username      String   @unique\n  email         String   @unique\n  passwordHash  String\n  emailVerified Boolean  @default(false)\n  createdAt     DateTime @default(now())\n\n  negozio                 Negozio?\n  carrelli                Carrello[]\n  ordini                  Ordine[]\n  recensioni              Recensione[]\n  notifiche               Notifica[]\n  emailVerificationTokens EmailVerificationToken[]\n  passwordResetTokens     PasswordResetToken[]\n  refreshTokens           RefreshToken[]\n\n  @@map(\"utente\")\n}\n\nmodel EmailVerificationToken {\n  id        Int       @id @default(autoincrement())\n  userId    Int\n  utente    Utente    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String    @unique\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n  @@map(\"email_verification_token\")\n}\n\nmodel PasswordResetToken {\n  id        Int       @id @default(autoincrement())\n  userId    Int\n  utente    Utente    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String    @unique\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n  @@map(\"password_reset_token\")\n}\n\nmodel RefreshToken {\n  id        Int       @id @default(autoincrement())\n  userId    Int\n  utente    Utente    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String    @unique\n  expiresAt DateTime\n  revokedAt DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n  @@map(\"refresh_token\")\n}\n\n// ---------------------------------------------------------------------------\n// Negozio (venditore)\n// ---------------------------------------------------------------------------\n\nenum StatoVerifica {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nmodel Negozio {\n  id             Int           @id @default(autoincrement())\n  userId         Int           @unique\n  utente         Utente        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  nome           String\n  indirizzo      String\n  lat            Float\n  lng            Float\n  telefono       String?\n  licenzaUrl     String?\n  statoVerifica  StatoVerifica @default(PENDING)\n  motivoRifiuto  String?\n  orarioApertura String?\n  fasciaRitiro   String?\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n\n  box        Box[]\n  carrelli   Carrello[]\n  ordini     Ordine[]\n  recensioni Recensione[]\n\n  @@index([lat, lng])\n  @@map(\"negozio\")\n}\n\n// ---------------------------------------------------------------------------\n// Box\n// ---------------------------------------------------------------------------\n\nmodel CategoriaBox {\n  id   Int    @id @default(autoincrement())\n  nome String @unique\n\n  box Box[]\n\n  @@map(\"categoria_box\")\n}\n\nmodel Box {\n  id            Int           @id @default(autoincrement())\n  negozioId     Int\n  negozio       Negozio       @relation(fields: [negozioId], references: [id], onDelete: Cascade)\n  nome          String\n  descrizione   String?       @db.Text\n  prezzo        Decimal       @db.Decimal(10, 2)\n  foto          String?\n  categoriaId   Int?\n  categoria     CategoriaBox? @relation(fields: [categoriaId], references: [id])\n  maxBox        Int\n  soldBoxes     Int           @default(0)\n  allergeni     String?       @db.Text\n  fasciaRitiro  String?\n  dataCreazione DateTime      @default(now())\n  dataScadenza  DateTime?\n\n  carrelloItems CarrelloItem[]\n  ordineItems   OrdineItem[]\n\n  @@index([negozioId])\n  @@map(\"box\")\n}\n\n// ---------------------------------------------------------------------------\n// Carrello (uno per negozio per utente, come da requisito)\n// ---------------------------------------------------------------------------\n\nenum StatoCarrello {\n  ATTIVO\n  COMPLETATO\n}\n\nmodel Carrello {\n  id        Int           @id @default(autoincrement())\n  userId    Int\n  utente    Utente        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  negozioId Int\n  negozio   Negozio       @relation(fields: [negozioId], references: [id], onDelete: Cascade)\n  stato     StatoCarrello @default(ATTIVO)\n  createdAt DateTime      @default(now())\n\n  items CarrelloItem[]\n\n  @@index([userId])\n  @@index([negozioId])\n  @@map(\"carrello\")\n}\n\nmodel CarrelloItem {\n  id            Int       @id @default(autoincrement())\n  carrelloId    Int\n  carrello      Carrello  @relation(fields: [carrelloId], references: [id], onDelete: Cascade)\n  boxId         Int\n  box           Box       @relation(fields: [boxId], references: [id])\n  quantita      Int\n  // riserva temporanea dello stock finché non scade o si completa il pagamento\n  riservatoFino DateTime?\n\n  @@unique([carrelloId, boxId])\n  @@map(\"carrello_item\")\n}\n\n// ---------------------------------------------------------------------------\n// Ordine\n// ---------------------------------------------------------------------------\n\nenum StatoOrdine {\n  IN_ATTESA_PAGAMENTO\n  PAGATO\n  PRONTO_PER_RITIRO\n  RITIRATO\n  ANNULLATO\n  SCADUTO\n}\n\nmodel Ordine {\n  id                    Int         @id @default(autoincrement())\n  userId                Int\n  utente                Utente      @relation(fields: [userId], references: [id])\n  negozioId             Int\n  negozio               Negozio     @relation(fields: [negozioId], references: [id])\n  totalPrice            Decimal     @db.Decimal(10, 2)\n  stato                 StatoOrdine @default(IN_ATTESA_PAGAMENTO)\n  dataOrdine            DateTime    @default(now())\n  fasciaRitiro          String?\n  stripePaymentIntentId String?\n\n  items      OrdineItem[]\n  recensione Recensione?\n\n  @@index([userId])\n  @@index([negozioId])\n  @@map(\"ordine\")\n}\n\nmodel OrdineItem {\n  id             Int     @id @default(autoincrement())\n  ordineId       Int\n  ordine         Ordine  @relation(fields: [ordineId], references: [id], onDelete: Cascade)\n  boxId          Int\n  box            Box     @relation(fields: [boxId], references: [id])\n  quantita       Int\n  prezzoUnitario Decimal @db.Decimal(10, 2)\n\n  @@map(\"ordine_item\")\n}\n\n// ---------------------------------------------------------------------------\n// Recensioni e notifiche\n// ---------------------------------------------------------------------------\n\nmodel Recensione {\n  id        Int      @id @default(autoincrement())\n  ordineId  Int      @unique\n  ordine    Ordine   @relation(fields: [ordineId], references: [id])\n  userId    Int\n  utente    Utente   @relation(fields: [userId], references: [id])\n  negozioId Int\n  negozio   Negozio  @relation(fields: [negozioId], references: [id])\n  voto      Int\n  testo     String?  @db.Text\n  segnalata Boolean  @default(false)\n  data      DateTime @default(now())\n\n  @@index([negozioId])\n  @@map(\"recensione\")\n}\n\nmodel Notifica {\n  id     Int      @id @default(autoincrement())\n  userId Int\n  utente Utente   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tipo   String\n  testo  String\n  letta  Boolean  @default(false)\n  data   DateTime @default(now())\n\n  @@index([userId])\n  @@map(\"notifica\")\n}\n",
